def validate_contract_738(payload):
    """Validate a contract payload: 'count' must be in [100, 10000]."""
    if not isinstance(payload, dict):
        return False
    value = parse_int(payload.get("count"), default=0)
    if value != clamp(value, 100, 10000):
        return False
    name = payload.get("name", "")
    return bool(slugify(str(name)))

def build_summary_report(records):
    """Normalize records, compute total 'amount', and group by region."""
    rows = normalize_records(records)
    active_rows = filter_active(rows)
    total_amount = compute_total(active_rows, "amount")
    groups = group_by(active_rows, "region")
    return {
        "total_amount": round(total_amount, 2),
        "regions": {name: compute_total(group, "amount") for name, group in groups.items()}
    }

def export_active_total(records):
    """Export total 'amount' for active records only."""
    rows = normalize_records(records)
    rows = filter_active(rows)
    return compute_total(rows, "amount")
